#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: fleet deploy, run with `nix run .#fleet-deploy`.
# ──────────────────────────────────────────────────────────────────────────

FLEET_ALL="kevin@kebean uribo@uribo-btw beellm@kebee kevin@beans-btw"
FLEET_DEFAULT="kevin@kebean uribo@uribo-btw beellm@kebee"
CACHE_HOST=uribo-btw
CACHE_URL=https://cache.beanhaven.net/nix-cache-info
CACHE_WAIT_SECONDS=120
CACHE_NOTE=""
STARTED=()
REPO=nixos-config
LOCAL_HOST=$(hostname -s)
ENV_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/fleet-deploy/env"

HOSTS=()
WORK=$(mktemp -d /tmp/fleet-deploy.XXXXXX)
SSH_OPTS=(
  -o BatchMode=yes
  -o ConnectTimeout=10
  -o ControlMaster=auto
  -o ControlPath="$WORK/%C"
  -o ControlPersist=yes
)

run_on() {
  local target="$1"; shift
  if [[ "${target#*@}" == "$LOCAL_HOST" ]]; then
    (cd "$HOME" && bash -c "$*")
  else
    ssh "${SSH_OPTS[@]}" "$target" "$@"
  fi
}

close_connections() {
  local target
  for target in "${HOSTS[@]}"; do
    ssh -o ControlPath="$WORK/%C" -O exit "$target" >/dev/null 2>&1 || true
  done
}

skip_host() {
  SKIPPED+=("${1#*@}: $2")
  warn "${1#*@}: $2, skipping this host"
}

require_hosts() {
  (( ${#HOSTS[@]} )) && return
  warn "$1"
  exit 1
}

start_rebuild() {
  local target name rebuild
  for target in "$@"; do
    name="${target#*@}"
    rebuild=nixos-rebuild
    [[ "$(cat "$WORK/$name.os")" == Darwin ]] && rebuild=darwin-rebuild
    (
      status=0
      printf '%s\n' "$SUDO_PASSWORD" | run_on "$target" \
        "sudo -k -S -p '' $rebuild switch --flake ./$REPO#$name" \
        > "$WORK/$name.log" 2>&1 || status=$?
      echo "$status" > "$WORK/$name.exit"
    ) &
    STARTED+=("$target")
  done
}

wave_finished() {
  local target
  for target in "$@"; do
    [[ -f "$WORK/${target#*@}.exit" ]] || return 1
  done
}

track_wave() {
  until wave_finished "$@"; do
    render_board
    sleep 3
  done
  render_board
}

wait_for_cache() {
  local deadline=$(( $(date +%s) + CACHE_WAIT_SECONDS ))
  CACHE_NOTE="waiting for $CACHE_URL"
  while ! curl -fsS --max-time 5 "$CACHE_URL" >/dev/null 2>&1; do
    if (( $(date +%s) >= deadline )); then
      CACHE_NOTE="cache unreachable, remaining hosts build from source"
      SKIPPED+=("$CACHE_URL was unreachable, hosts may have built from source")
      warn "$CACHE_NOTE"
      return
    fi
    render_board
    sleep 3
  done
  CACHE_NOTE="cache up"
}

render_board() {
  local target name exit_file secs
  secs=$(( $(date +%s) - STARTED_AT ))
  _clear
  printf '\n%s%s▸ Stage %s/%s · Rebuilding%s   %s%dm%02ds elapsed%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$RESET" "$DIM" $((secs / 60)) $((secs % 60)) "$RESET"
  for target in "${HOSTS[@]}"; do
    name="${target#*@}"
    exit_file="$WORK/$name.exit"
    if [[ ! -f "$WORK/$name.log" ]]; then
      printf '  %s· %-12s queued%s\n' "$DIM" "$name" "$RESET"
    elif [[ ! -f "$exit_file" ]]; then
      printf '  %s⟳ %-12s%s in progress  %s%s%s\n' "$YELLOW" "$name" "$RESET" \
        "$DIM" "$(tail -n1 "$WORK/$name.log" 2>/dev/null | cut -c1-70)" "$RESET"
    elif [[ "$(cat "$exit_file")" == 0 ]]; then
      printf '  %s✓ %-12s%s done\n' "$GREEN" "$name" "$RESET"
    else
      printf '  %s✗ %-12s%s failed (exit %s)\n' "$YELLOW" "$name" "$RESET" "$(cat "$exit_file")"
    fi
  done
  printf '\n'
  [[ -n "$CACHE_NOTE" ]] && note "$CACHE_NOTE"
  note "logs: $WORK/<host>.log"
}

run_wizard() {

TOTAL_STAGES=5

mkdir -p "$(dirname "$ENV_FILE")"
trap 'close_connections' EXIT

banner "Fleet deploy"

stage "Pick hosts"
say "Hosts are user@host, reached over tailscale. $LOCAL_HOST runs locally."
note "Arrows move, x or tab toggles, enter confirms."
printf '\n'
read -r -a choices <<< "$FLEET_ALL"
read -r -a remembered <<< "$(_existing FLEET_HOSTS || printf '%s' "$FLEET_DEFAULT")"
mapfile -t HOSTS < <(printf '%s\n' "${choices[@]}" |
  gum choose --no-limit --height "$(( ${#choices[@]} + 1 ))" \
    --header "Hosts to deploy" \
    --selected "$(IFS=,; printf '%s' "${remembered[*]}")")
require_hosts "no hosts selected"
write_env FLEET_HOSTS "${HOSTS[*]}"

stage "Connect"
say "Opening one persistent SSH connection per host. Later stages reuse it."
kept=()
for target in "${HOSTS[@]}"; do
  if os=$(run_on "$target" uname -s 2>/dev/null); then
    printf '  %s✓ connected%s %-20s %s\n' "$GREEN" "$RESET" "$target" "$os"
    printf '%s' "$os" > "$WORK/${target#*@}.os"
    kept+=("$target")
  else
    skip_host "$target" "unreachable"
  fi
done
HOSTS=("${kept[@]}")
require_hosts "no reachable hosts"
pause

stage "Sudo password"
say "The rebuild needs sudo on each host. The password is only"
say "piped to sudo over SSH; it is never written to disk."
ask_secret SUDO_PASSWORD "Sudo password for the fleet:"
kept=()
for target in "${HOSTS[@]}"; do
  if printf '%s\n' "$SUDO_PASSWORD" | run_on "$target" "sudo -k -S -p '' true" >/dev/null 2>&1; then
    printf '  %s✓ sudo ok%s %s\n' "$GREEN" "$RESET" "${target#*@}"
    kept+=("$target")
  else
    skip_host "$target" "sudo rejected the password"
  fi
done
HOSTS=("${kept[@]}")
require_hosts "sudo failed on every host"
pause

stage "Pull latest main"
say "Fast-forwarding ~/$REPO to origin/main on every host."
kept=()
for target in "${HOSTS[@]}"; do
  if [[ -n "$(run_on "$target" "git -C $REPO status --porcelain --untracked-files=no")" ]]; then
    skip_host "$target" "working tree has uncommitted changes"
    continue
  fi
  if head=$(run_on "$target" "git -C $REPO fetch -q origin main && git -C $REPO switch -q main && git -C $REPO merge -q --ff-only origin/main && git -C $REPO log --oneline -1" 2>&1); then
    printf '  %s✓ %-12s%s %s\n' "$GREEN" "${target#*@}" "$RESET" "$head"
    kept+=("$target")
  else
    skip_host "$target" "git pull failed: $head"
  fi
done
HOSTS=("${kept[@]}")
require_hosts "nothing left to deploy"
printf '\n'
confirm "Rebuild and switch ${#HOSTS[@]} host(s) now?" || exit 1

stage "Rebuilding"
warn "Keep this terminal open: closing it kills the SSH sessions mid-switch."
say "$CACHE_HOST and the darwin hosts go first. Darwin does not pull from the"
say "cache, so it is safe to rebuild those while the cache host restarts."
say "The remaining linux hosts start once the cache answers again."
STARTED_AT=$(date +%s)

cache_target=""
independent=()
cache_users=()
for target in "${HOSTS[@]}"; do
  name="${target#*@}"
  if [[ "$name" == "$CACHE_HOST" ]]; then
    cache_target="$target"
    independent+=("$target")
  elif [[ "$(cat "$WORK/$name.os")" == Darwin ]]; then
    independent+=("$target")
  else
    cache_users+=("$target")
  fi
done

(( ${#independent[@]} )) && start_rebuild "${independent[@]}"

if (( ${#cache_users[@]} )) && [[ -n "$cache_target" ]]; then
  track_wave "$cache_target"
  if [[ "$(cat "$WORK/$CACHE_HOST.exit")" != 0 ]]; then
    printf '\n'; warn "$CACHE_HOST failed, so its cache may be stale or down."
    if ! confirm "Rebuild the remaining ${#cache_users[@]} linux host(s) anyway?"; then
      for target in "${cache_users[@]}"; do
        SKIPPED+=("${target#*@}: not rebuilt, $CACHE_HOST failed first")
      done
      cache_users=()
    fi
  fi
  (( ${#cache_users[@]} )) && wait_for_cache
fi

(( ${#cache_users[@]} )) && start_rebuild "${cache_users[@]}"

track_wave "${STARTED[@]}"

for target in "${HOSTS[@]}"; do
  name="${target#*@}"
  [[ -f "$WORK/$name.exit" ]] || continue
  [[ "$(cat "$WORK/$name.exit")" == 0 ]] && continue
  printf '\n'; warn "$name failed, last lines of $WORK/$name.log:"
  tail -n 15 "$WORK/$name.log" | sed 's/^/      /'
  SKIPPED+=("$name: rebuild failed, see $WORK/$name.log")
done
pause

finish
}

run_wizard "$@"; exit
